import * as THREE from 'three/webgpu';
import { texture, uv, vec2 } from 'three/tsl';

export default function createNode(config, ctx) {
  const group = new THREE.Group();
  group.name = 'hub-features-card-2-accent';

  const atlasIndex = 0;
  const rect = { x: 0, y: 0, w: 512, h: 320 };
  const atlasSize = 512;

  const aspect = rect.w / rect.h;
  const baseHeight = 1.0;
  const baseWidth = baseHeight * aspect;

  const geometry = new THREE.PlaneGeometry(baseWidth, baseHeight);

  const map = ctx.textureLoader.load(config.assets?.imageUrl || '/prism-mock/home/nodes/floating-accent.png');
  map.colorSpace = THREE.SRGBColorSpace;
  map.wrapS = THREE.ClampToEdgeWrapping;
  map.wrapT = THREE.ClampToEdgeWrapping;

  const offsetX = rect.x / atlasSize;
  const offsetY = 1.0 - (rect.y + rect.h) / atlasSize;
  const scaleX = rect.w / atlasSize;
  const scaleY = rect.h / atlasSize;

  const uvNode = uv().mul(vec2(scaleX, scaleY)).add(vec2(offsetX, offsetY));
  const mapNode = texture(map, uvNode);

  const material = new THREE.MeshBasicNodeMaterial({ transparent: true });
  material.colorNode = mapNode;
  material.opacityNode = mapNode.a;

  const mesh = new THREE.Mesh(geometry, material);
  mesh.name = 'features-card-2-accent-sprite';
  group.add(mesh);

  group.position.set(0, -0.3, 0);
  group.rotation.set(0, 0, 0);
  group.scale.set(1, 1, 1);

  group.onBeforeRender = (renderer, scene, camera) => {
    mesh.quaternion.copy(camera.quaternion);
  };

  group.userData.handlers = {};

  group.userData.cleanup = () => {
    geometry.dispose();
    material.dispose();
    if (map && map.dispose) map.dispose();
    group.onBeforeRender = null;
  };

  return group;
}
